script:
var hull0 = 0, kills = 0;
VTL.on('runStart', function(){ kills = 0; });
VTL.on('combatStart', function(){ var G = VTL.G; if(G && G.ship) hull0 = G.ship.hull; });
VTL.on('combatEnd', function(o){
  var G = VTL.G; if(!G || !G.ship || !o) return;
  var bonus = 0, why = [];
  if((G.combatT || 0) < 40){ bonus += 8; why.push('quick kill'); }
  if(G.ship.hull >= hull0){ bonus += 10; why.push('no hull damage'); }
  kills++; if(kills % 5 === 0){ bonus += 15; why.push(kills + ' kills this run'); }
  if(bonus){ VTL.applyEffect({ scrap: bonus }); VTL.toast('Combat bonus +' + bonus + ' scrap: ' + why.join(', ') + '.'); }
});
